import java.util.Optional;

public class Email {
    static Optional<String> domaineMajuscule(Optional<String> email) {
        return email
            .filter(e -> e.contains("@"))
            .map(e -> e.substring(e.indexOf('@') + 1).toUpperCase());
    }
}
